  ],
  "indicator_readings": [
    {
      "indicator": "MM20",
      "reading": "14.3210",
      "interpretation": "MM de curto prazo; preço (14,13) fechou abaixo da MM20 — recuo técnico; MM20 ainda acima da MM50 indicando viés altista de médio prazo."
    },
    {
      "indicator": "MM50",
      "reading": "13.6036",
      "interpretation": "Suporte de médio prazo; preço está acima da MM50, confirmando tendência positiva no médio prazo."
    },
    {
      "indicator": "MM200",
      "reading": "11.3405",
      "interpretation": "Tendência de longo prazo altista (MM200 bem abaixo do preço atual)."
    },
    {
      "indicator": "EMA9",
      "reading": "14.0531",
      "interpretation": "EMA9 abaixo do preço atual e acima da EMA21 — curto viés levemente altista, mas sensível a reversões."
    },
    {
      "indicator": "EMA21",
      "reading": "14.0249",
      "interpretation": "EMA21 confirma suporte de curtíssimo prazo; preço está ligeiramente acima."
    },
    {
      "indicator": "MACD",
      "reading": "0.0907",
      "interpretation": "MACD positivo, mas abaixo da linha de sinal — momentum comprador presente porém enfraquecendo."
    },
    {
      "indicator": "MACD_signal",
      "reading": "0.1416",
      "interpretation": "Linha de sinal acima do MACD atual; demanda confirmação de retorno do MACD acima desta linha."
    },
    {
      "indicator": "MACD_hist",
