    },
    {
      "indicator": "BB_mid",
      "reading": "14.3210",
      "interpretation": "Equivale à MM20; preço ligeiramente abaixo, atuando como resistência de curto prazo."
    },
    {
      "indicator": "BB_upper",
      "reading": "15.5173",
      "interpretation": "Resistência superior e alvo lógico em ralis; banda ainda está larga (volatilidade elevada)."
    },
    {
      "indicator": "RSI14",
      "reading": "52.2195",
      "interpretation": "Neutro — não indica sobrecompra nem sobrevenda."
    },
    {
